```python
def longest_common_subsequence(w, x, y, z):
    l = len(w)
    m = len(x)
    n = len(y)
    p = len(z)

    L = [[[[0 for i in range(p+1)] for j in range(n+1)] for k in range(m+1)] for h in range(l+1)]

    for h in range(l+1):
        for i in range(m+1):
            for j in range(n+1):
                for k in range(p+1):
                    if h == 0 or i == 0 or j == 0 or k == 0:
                        L[h][i][j][k] = 0
                    elif w[h-1] == x[i-1] == y[j-1] == z[k-1]:
                        L[h][i][j][k] = L[h-1][i-1][j-1][k-1] + 1
                    else:
                        L[h][i][j][k] = max(max(max(L[h-1][i][j][k], L[h][i-1][j][k]), L[h][i][j-1][k]), L[h][i][j][k-1])

    return L[l][m][n][p]
