    private static boolean isValidFibo(ArrayList<Integer> array){
        if(array.size() < 3) {
            return false;
        }
        for(int i=2; i<array.size(); ++i){
            if(array.get(i-2) + array.get(i-1) != array.get(i)){
                return false;
            }
        }
        return true;
    }
}
